//! Section-level contract vectors (FireLine's five requests): whole seven-section documents that
//! a foreign reader must ACCEPT, and single-fault documents it must DECLINE with a stable tag.
//!
//! Everything here is generated by the library: the accept documents are assembled from the
//! Appendix C block builders with one section changed, and the decline documents are those with
//! exactly ONE fault. The generator states the `(section, tag)` it intends for each decline and
//! [`read_full_document`] — the reader the tests run — must return exactly that pair, so an
//! intended tag that the reader does not produce fails the build rather than being emitted.
//!
//! The tags are `wire_tag()` strings (stable kebab-case categories, no payload), never `Debug`.

use crate::contract::{
    appendix_c_capabilities_block, appendix_c_dispatch_block, appendix_c_guarantees_block,
    appendix_c_identity_block, appendix_c_interface_block, appendix_c_provenance_block,
    appendix_c_semantics_block, check_record_consistency,
    parse_capabilities_block, parse_guarantees_block, parse_identity_block,
    parse_interface_block, parse_provenance_block, parse_semantics_block, read_document,
    render_block, section_block, Document, RecordDecline, Value,
};
use crate::dispatch::{parse_dispatch_block, DispatchDecline, DispatchModel};
use crate::dispatch_expr::{eval, Decline, EvalMode, LaunchScalars};

// ---------------------------------------------------------------------------
// The positional_signature descriptor layout (§6.11-0006) and its typed decline.
// ---------------------------------------------------------------------------

/// One `positional_signature` argument descriptor `(<arg_kind>, <launch_class>, <arg_name>,
/// <type_token>, <dtype>, <array_len_kind>)` (§6.11-0006).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SignatureArg {
    pub arg_kind: String,
    pub launch_class: u8,
    pub arg_name: String,
    pub type_token: String,
    pub dtype: String,
    pub array_len_kind: String,
}

/// A typed decline from reading a `positional_signature` value. Never a panic.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SignatureDecline {
    /// The value or a descriptor is outside the §6.11-0006 layout.
    BadDescriptor(String),
    /// A launch-scalar class whose array-ness is pinned by §6.5-0004a disagrees with the
    /// descriptor's `array_len_kind`: extents (class 1) and strides (class 2) are rank-length
    /// arrays, `n` (class 3) and `off{i}` (class 4) are scalars (V11, §6.5-0005).
    ArrayLenKindMismatch { name: String, expected: &'static str },
}

impl SignatureDecline {
    /// The stable kebab-case category tag (payload omitted).
    pub fn wire_tag(&self) -> &'static str {
        match self {
            SignatureDecline::BadDescriptor(_) => "bad-descriptor",
            SignatureDecline::ArrayLenKindMismatch { .. } => "array-len-kind-mismatch",
        }
    }
}

fn is_token(s: &str) -> bool {
    !s.is_empty() && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn parse_descriptor(inner: &str) -> Result<SignatureArg, SignatureDecline> {
    let bad = || SignatureDecline::BadDescriptor(inner.to_string());
    let parts: Vec<&str> = inner.split(", ").collect();
    if parts.len() != 6 || !parts.iter().all(|p| is_token(p) || p.contains('@')) {
        return Err(bad());
    }
    let class: u8 = parts[1].parse().map_err(|_| bad())?;
    let valid_class = match parts[0] {
        "ptr" => class == 0,
        "ls" => (1..=8).contains(&class),
        "idesc" => class == 5,
        _ => false,
    };
    if !valid_class || parts[1] != class.to_string() {
        return Err(bad());
    }
    let arg = SignatureArg {
        arg_kind: parts[0].into(),
        launch_class: class,
        arg_name: parts[2].into(),
        type_token: parts[3].into(),
        dtype: parts[4].into(),
        array_len_kind: parts[5].into(),
    };
    let len_ok = if arg.arg_kind == "idesc" {
        arg.array_len_kind.split_once('@').is_some_and(|(r, e)| !r.is_empty() && r.bytes().all(|b| b.is_ascii_digit()) && is_token(e))
    } else {
        arg.array_len_kind == "scalar" || arg.array_len_kind == "rank"
    };
    if !len_ok {
        return Err(bad());
    }
    let expected = match (arg.arg_kind.as_str(), arg.launch_class) {
        ("ls", 1) | ("ls", 2) => Some("rank"),
        ("ls", 3) | ("ls", 4) => Some("scalar"),
        _ => None,
    };
    match expected {
        Some(e) if arg.array_len_kind != e => {
            Err(SignatureDecline::ArrayLenKindMismatch { name: arg.arg_name.clone(), expected: e })
        }
        _ => Ok(arg),
    }
}

/// Read a `positional_signature` value: `[` then parenthesized six-slot descriptors separated by
/// `, ` then `]` (§6.11-0001, §6.11-0006), each launch-scalar class's array-ness checked.
pub fn parse_positional_signature(value: &str) -> Result<Vec<SignatureArg>, SignatureDecline> {
    let bad = || SignatureDecline::BadDescriptor(value.to_string());
    let inner = value.strip_prefix('[').and_then(|v| v.strip_suffix(']')).ok_or_else(bad)?;
    if inner.is_empty() {
        return Ok(Vec::new());
    }
    let mut out = Vec::new();
    for d in inner.split("), (") {
        let d = d.strip_prefix('(').unwrap_or(d);
        let d = d.strip_suffix(')').unwrap_or(d);
        out.push(parse_descriptor(d)?);
    }
    Ok(out)
}

impl DispatchDecline {
    /// The stable kebab-case category tag (payload omitted).
    pub fn wire_tag(&self) -> &'static str {
        match self {
            DispatchDecline::BadHeading => "bad-heading",
            DispatchDecline::Empty => "empty-section",
            DispatchDecline::UnknownField(_) => "unknown-field",
            DispatchDecline::PartialGeometry => "partial-geometry",
            DispatchDecline::SentinelWithGeometry => "sentinel-with-geometry",
            DispatchDecline::BadSentinelValue(_) => "bad-sentinel-value",
            DispatchDecline::MalformedLine(_) => "malformed-line",
            DispatchDecline::MissingSection => "missing-section",
        }
    }
}

fn expr_tag(d: &Decline) -> &'static str {
    match d {
        Decline::UnknownSymbol(_) => "unknown-symbol",
        Decline::SubscriptOfScalar(_) => "subscript-of-scalar",
        Decline::BareArraySymbol(_) => "bare-array-symbol",
        Decline::SubscriptOutOfBounds { .. } => "subscript-out-of-bounds",
        _ => "bad-expression",
    }
}

// ---------------------------------------------------------------------------
// The full-document reader the vectors are checked against.
// ---------------------------------------------------------------------------

/// Where a full-document read declined and the stable tag it declined with.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FullDecline {
    /// `framing`, a section name (`identity` .. `provenance`), or `record` (a cross-section rule).
    pub section: &'static str,
    pub tag: &'static str,
}

const SECTIONS: [(u8, &str); 7] = [
    (1, "identity"),
    (2, "semantics"),
    (3, "interface"),
    (4, "dispatch"),
    (5, "capabilities"),
    (6, "guarantees"),
    (7, "provenance"),
];

fn fd(section: &'static str, tag: &'static str) -> FullDecline {
    FullDecline { section, tag }
}

/// The reference launch-scalar environment for a signature: representative extents and strides of
/// the contract's rank, and only the classes the signature declares (§6.5-0004a), so a symbol of
/// an undeclared class is outside the vocabulary.
fn environment(rank: u32, sig: &[SignatureArg]) -> LaunchScalars {
    let named = |prefix: &str| sig.iter().filter(|a| a.arg_kind == "ls" && a.arg_name.starts_with(prefix)).count();
    let row = |base: i64| (0..i64::from(rank)).map(|k| base + k).collect::<Vec<i64>>();
    LaunchScalars {
        rank,
        n: 32,
        extents: (0..named("extents")).map(|_| row(4)).collect(),
        strides: (0..named("strides")).map(|_| row(1)).collect(),
        idx_extents: Vec::new(),
        off: vec![0; named("off")],
        ws_bytes: None,
        param: Vec::new(),
    }
}

fn check_interface(block: &[u8]) -> Result<(u32, Vec<SignatureArg>), FullDecline> {
    let fields = parse_interface_block(block).map_err(|d| fd("interface", d.wire_tag()))?;
    let get = |k: &str| fields.iter().find(|(n, _)| n == k).map(|(_, v)| v.as_str()).unwrap_or("");
    let sig = parse_positional_signature(get("positional_signature")).map_err(|d| fd("interface", d.wire_tag()))?;
    let rank = get("rank").parse::<u32>().map_err(|_| fd("interface", "bad-field-value"))?;
    Ok((rank, sig))
}

fn check_dispatch(block: &[u8], rank: u32, sig: &[SignatureArg]) -> Result<(), FullDecline> {
    let model = parse_dispatch_block(block).map_err(|d| fd("dispatch", d.wire_tag()))?;
    if let DispatchModel::Declared(f) = model {
        let env = environment(rank, sig);
        for (name, mode) in [
            ("invocation_domain", EvalMode::Domain),
            ("workgroup_sizing", EvalMode::Domain),
            ("count_to_grid", EvalMode::Domain),
            ("thread_mapping", EvalMode::Structural),
            ("addressing_rule", EvalMode::Structural),
        ] {
            eval(f.field(name), &env, mode).map_err(|d| fd("dispatch", expr_tag(&d)))?;
        }
    }
    Ok(())
}

/// Read a whole contract document: transport framing, then each of the seven sections in document
/// order (schema, then the section's own value rules), then the cross-section equalities.
/// The first fault is returned as `(section, tag)`.
pub fn read_full_document(doc: &[u8]) -> Result<(), FullDecline> {
    read_document(doc).map_err(|d| fd("framing", d.wire_tag()))?;
    let lf = doc.iter().position(|&b| b == b'\n').unwrap_or(0);
    let body = &doc[lf + 1..];
    let (mut rank, mut sig) = (0, Vec::new());
    for (id, name) in SECTIONS {
        let sname: &'static str = name_static(name);
        let block = section_block(body, id, name).ok_or(fd(sname, "missing-section"))?;
        let r = match id {
            1 => parse_identity_block(block).map(|_| ()),
            2 => parse_semantics_block(block).map(|_| ()),
            5 => parse_capabilities_block(block).map(|_| ()),
            6 => parse_guarantees_block(block).map(|_| ()),
            7 => parse_provenance_block(block).map(|_| ()),
            3 => {
                (rank, sig) = check_interface(block)?;
                Ok(())
            }
            _ => Ok(check_dispatch(block, rank, &sig)?),
        };
        r.map_err(|d| fd(sname, d.wire_tag()))?;
    }
    check_record_consistency(doc).map_err(|d| match d {
        RecordDecline::Framing(_) => fd("framing", "framing"),
        RecordDecline::MissingSection(_) => fd("record", "missing-section"),
        RecordDecline::Section { section, decline } => fd(section, decline.wire_tag()),
        RecordDecline::IdentityHeaderMismatch { .. } => fd("record", "identity-header-mismatch"),
        RecordDecline::AcceptPredicateMismatch { .. } => fd("record", "accept-predicate-mismatch"),
        RecordDecline::RevisionHashMismatch { .. } => fd("record", "revision-hash-mismatch"),
        RecordDecline::CostProvenanceMismatch { .. } => fd("record", "cost-provenance-mismatch"),
    })
}

fn name_static(name: &str) -> &'static str {
    SECTIONS.iter().map(|&(_, n)| n).find(|n| *n == name).unwrap_or("")
}

// ---------------------------------------------------------------------------
// The vector sets.
// ---------------------------------------------------------------------------

/// An accept vector: a whole document every conforming reader reads cleanly.
pub struct AcceptVector {
    pub name: String,
    pub doc: Vec<u8>,
}

/// A decline vector: one fault, the section it is in and the stable tag the reader returns.
pub struct SectionDeclineVector {
    pub name: String,
    pub doc: Vec<u8>,
    pub section: &'static str,
    pub expect: &'static str,
}

type Fields = Vec<(String, String)>;

fn base_blocks() -> Vec<Vec<u8>> {
    vec![
        appendix_c_identity_block(),
        appendix_c_semantics_block(),
        appendix_c_interface_block(),
        appendix_c_dispatch_block(),
        appendix_c_capabilities_block(),
        appendix_c_guarantees_block(),
        appendix_c_provenance_block(),
    ]
}

fn fields_of(block: &[u8]) -> Fields {
    let text = String::from_utf8(block.to_vec()).expect("builder blocks are UTF-8");
    text.lines()
        .skip(1)
        .filter_map(|l| l.split_once(" = ").map(|(k, v)| (k.to_string(), v.to_string())))
        .collect()
}

fn render(index: usize, fields: &Fields) -> Vec<u8> {
    let (id, name) = SECTIONS[index];
    let f: Vec<(&str, Value)> = fields.iter().map(|(k, v)| (k.as_str(), Value::Str(v.clone()))).collect();
    render_block(id, name, &f)
}

fn assemble(blocks: &[Vec<u8>]) -> Vec<u8> {
    let body: Vec<u8> = blocks.iter().flatten().copied().collect();
    Document { contract_kind: "kiss-contract".into(), contract_version: "4".into(), body }.encode()
}

fn set(fields: &mut Fields, key: &str, value: &str) {
    let slot = fields.iter_mut().find(|(k, _)| k == key).expect("field present in the base block");
    slot.1 = value.to_string();
}

/// The strided `add` signature of the Appendix C contract: three rank-2 operands (in0, in1, out0),
/// their extents (class 1), signed strides (class 2) and the iteration count `n` (class 3, `i32`
/// for the `ix32` cell), §6.5-0002/-0004a/-0005, in the §6.11-0006 descriptor layout. Returns the
/// whole `positional_signature` value and its launch-scalar tail (§6.5-0011).
pub fn strided_signature() -> (String, String) {
    let ptrs = ["in0", "in1", "out0"].map(|n| format!("(ptr, 0, {n}, ptr_f32, f32, scalar)"));
    let mut tail: Vec<String> = (0..3).map(|i| format!("(ls, 1, extents{i}, i64, -, rank)")).collect();
    tail.extend((0..3).map(|i| format!("(ls, 2, strides{i}, i64, -, rank)")));
    tail.push("(ls, 3, n, i32, -, scalar)".to_string());
    let all: Vec<String> = ptrs.iter().cloned().chain(tail.iter().cloned()).collect();
    (format!("[{}]", all.join(", ")), format!("[{}]", tail.join(", ")))
}

fn strided_interface() -> Fields {
    let mut f = fields_of(&appendix_c_interface_block());
    let (sig, tail) = strided_signature();
    set(&mut f, "positional_signature", &sig);
    set(&mut f, "launch_scalars", &tail);
    f
}

fn with(index: usize, block: Vec<u8>) -> Vec<Vec<u8>> {
    let mut b = base_blocks();
    b[index] = block;
    b
}

const FIVE_FIELDS: [(&str, &str); 5] = [
    ("invocation_domain", "extents0[0]*extents0[1]"),
    ("workgroup_sizing", "256"),
    ("count_to_grid", "ceil_div(n, 256)"),
    ("thread_mapping", "256*ceil_div(n, 256)"),
    ("addressing_rule", "strides0[0]+strides0[1]"),
];

fn dispatch_fields(edit: impl Fn(&mut Fields)) -> Fields {
    let mut f: Fields = FIVE_FIELDS.iter().map(|&(k, v)| (k.to_string(), v.to_string())).collect();
    edit(&mut f);
    f
}

/// The documents a reader accepts (requests 1-4): the strided signature, the five-field Dispatch,
/// the optional trailing `output_layouts` and `human_annotation`, and the aliased `in_place` forms.
pub fn accept_vectors() -> Vec<AcceptVector> {
    let strided = |f: Fields| with(2, render(2, &f));
    let mut v = vec![("strided-signature", strided(strided_interface()))];
    let mut five = strided(strided_interface());
    five[3] = render(3, &dispatch_fields(|_| {}));
    v.push(("five-field-dispatch", five));
    let mut layouts = fields_of(&appendix_c_interface_block());
    layouts.push(("output_layouts".into(), "[dense]".into()));
    v.push(("output-layouts-present", with(2, render(2, &layouts))));
    let mut sem = fields_of(&appendix_c_semantics_block());
    sem.push(("human_annotation".into(), "elementwise add of two tensors".into()));
    v.push(("human-annotation-present", with(1, render(1, &sem))));
    for k in 0..2 {
        v.push(("in-place-input", in_place_doc(&format!("input:{k}"), k)));
    }
    v.into_iter()
        .enumerate()
        .map(|(i, (name, blocks))| AcceptVector {
            name: if name == "in-place-input" { format!("in-place-input:{}", i - 4) } else { name.to_string() },
            doc: assemble(&blocks),
        })
        .collect()
}

fn in_place_doc(value: &str, variant: usize) -> Vec<Vec<u8>> {
    let mut iface = strided_interface();
    set(&mut iface, "in_place", value);
    let mut caps = fields_of(&appendix_c_capabilities_block());
    set(&mut caps, "in_place_eligible_variants", &format!("[in{variant}]"));
    let mut b = with(2, render(2, &iface));
    b[4] = render(4, &caps);
    b
}

fn push(
    out: &mut Vec<SectionDeclineVector>,
    name: String,
    blocks: &[Vec<u8>],
    section: &'static str,
    expect: &'static str,
) {
    out.push(SectionDeclineVector { name, doc: assemble(blocks), section, expect });
}

/// Requests 1 (V11), 2, 3 and 4: the feature-specific declines.
fn feature_declines(out: &mut Vec<SectionDeclineVector>) {
    let mut f = strided_interface();
    let (sig, _) = strided_signature();
    set(&mut f, "positional_signature", &sig.replace("(ls, 2, strides0, i64, -, rank)", "(ls, 2, strides0, i64, -, scalar)"));
    push(out, "strided stride descriptor declared scalar (V11)".into(), &with(2, render(2, &f)), "interface", "array-len-kind-mismatch");
    let mut f = strided_interface();
    set(&mut f, "positional_signature", &sig.replace("(ls, 1, extents0, i64, -, rank)", "(ls, 1, extents0, i64, rank)"));
    push(out, "descriptor with five slots".into(), &with(2, render(2, &f)), "interface", "bad-descriptor");

    let five = |blocks: Fields| {
        let mut b = with(2, render(2, &strided_interface()));
        b[3] = render(3, &blocks);
        b
    };
    push(out, "dispatch: a field missing".into(), &five(dispatch_fields(|f| { f.remove(2); })), "dispatch", "partial-geometry");
    push(out, "dispatch: fields out of order".into(), &five(dispatch_fields(|f| f.swap(0, 1))), "dispatch", "partial-geometry");
    push(
        out,
        "dispatch: geometry-agnostic sentinel plus a field".into(),
        &five(dispatch_fields(|f| f.insert(0, ("dispatch_model".into(), "geometry-agnostic".into())))),
        "dispatch",
        "sentinel-with-geometry",
    );
    for (what, value, tag) in [
        ("unparseable expression", "ceil_div(n 256)", "bad-expression"),
        ("symbol outside the vocabulary", "off0", "unknown-symbol"),
        ("array symbol without a subscript", "extents0", "bare-array-symbol"),
    ] {
        let b = five(dispatch_fields(|f| set(f, "count_to_grid", value)));
        push(out, format!("dispatch: count_to_grid is an {what}"), &b, "dispatch", tag);
    }

    let mut f = fields_of(&appendix_c_interface_block());
    f.insert(f.len() - 1, ("output_layouts".into(), "[dense]".into()));
    push(out, "output_layouts not last in Interface".into(), &with(2, render(2, &f)), "interface", "out-of-order");
    let mut f = fields_of(&appendix_c_semantics_block());
    f.insert(1, ("human_annotation".into(), "a note".into()));
    push(out, "human_annotation before op_dag in Semantics".into(), &with(1, render(1, &f)), "semantics", "out-of-order");

    for bad in ["false", "input:01", "input:"] {
        let mut f = strided_interface();
        set(&mut f, "in_place", bad);
        push(out, format!("in_place = {bad}"), &with(2, render(2, &f)), "interface", "bad-field-value");
    }
}

/// Request 5: per section, one fault of each kind the field schema rules out.
fn schema_declines(out: &mut Vec<SectionDeclineVector>) {
    let blocks = base_blocks();
    for (i, (_, name)) in SECTIONS.iter().enumerate() {
        if *name == "dispatch" {
            continue; // Dispatch has its own either/or schema; its declines are in `feature_declines`.
        }
        let sname = name_static(name);
        let fields = fields_of(&blocks[i]);
        let mut put = |what: &str, block: Vec<u8>, tag: &'static str| {
            let mut b = base_blocks();
            b[i] = block;
            push(out, format!("{name}: {what}"), &b, sname, tag);
        };
        let mut f = fields.clone();
        f.remove(1);
        put("a field dropped", render(i, &f), "missing-field");
        let mut f = fields.clone();
        f.push(("bogus_field".into(), "x".into()));
        put("an unknown key", render(i, &f), "unknown-field");
        let mut f = fields.clone();
        f.swap(0, 1);
        put("two keys swapped", render(i, &f), "out-of-order");
        let mut f = fields.clone();
        f.insert(1, f[0].clone());
        put("a key repeated", render(i, &f), "duplicate-field");
        let mut raw = render(i, &fields);
        raw.splice(raw.len() - 1..raw.len() - 1, [0xFFu8]);
        put("a non-UTF-8 byte", raw, "not-utf8");
        let mut f = fields.clone();
        f[0].1.push('\r');
        put("a line ending in CR", render(i, &f), "malformed-line");
    }
}

/// Every section-level decline vector, in a fixed order.
pub fn section_decline_vectors() -> Vec<SectionDeclineVector> {
    let mut out = Vec::new();
    feature_declines(&mut out);
    schema_declines(&mut out);
    out
}

/// The `section_vectors` key of `contract_vectors.json`: the accept documents and the section
/// declines, as hex of the whole document. Rendered here so the generator is one function.
pub fn emit_section_vectors_json() -> String {
    let jstr = crate::json::escape_string;
    let hex = crate::hex;
    let mut s = String::new();
    s.push_str("  \"section_vectors\": {\n");
    s.push_str("    \"spec_reference\": \"spec/contract.md 6.4-0001, 6.5-0001/-0002/-0005/-0009/-0014, 6.6-0001/-0006, 6.11-0001/-0005/-0006: whole seven-section documents (header v4), ONE feature or fault each\",\n");
    s.push_str("    \"encoding_note\": \"accept_vectors[].doc_hex must read cleanly. decline_vectors[].section names where the reader declines (framing, a section name, or record) and expect is that decline's stable kebab-case tag; the payload is omitted. Tags per section: missing-field, unknown-field, out-of-order, duplicate-field, forbidden-field, bad-field-value, not-utf8, malformed-line, bad-heading; interface adds bad-descriptor, array-len-kind-mismatch; dispatch adds partial-geometry (a missing or misordered geometry field), sentinel-with-geometry, bad-expression, unknown-symbol, bare-array-symbol, subscript-of-scalar, subscript-out-of-bounds. Pointer descriptors write type_token ptr_<dtype>; the n scalar is i32 for the ix32 cell.\",\n");
    s.push_str("    \"accept_vectors\": [\n");
    let accepts = accept_vectors();
    for (i, v) in accepts.iter().enumerate() {
        let comma = if i + 1 < accepts.len() { "," } else { "" };
        s.push_str(&format!("      {{\"name\": {}, \"doc_hex\": {}}}{comma}\n", jstr(&v.name), jstr(&hex(&v.doc))));
    }
    s.push_str("    ],\n");
    s.push_str("    \"decline_vectors\": [\n");
    let declines = section_decline_vectors();
    for (i, v) in declines.iter().enumerate() {
        let comma = if i + 1 < declines.len() { "," } else { "" };
        s.push_str(&format!(
            "      {{\"name\": {}, \"doc_hex\": {}, \"section\": {}, \"expect\": {}}}{comma}\n",
            jstr(&v.name),
            jstr(&hex(&v.doc)),
            jstr(v.section),
            jstr(v.expect)
        ));
    }
    s.push_str("    ]\n");
    s.push_str("  },\n");
    s
}
